function intersect(node1, node2) {
1. if (node1.isLeaf) return node1.val ? node1 : node2;
2. if (node2.isLeaf) return node2.val ? node2 : node1;
3. let tl = intersect(node1.topLeft, node2.topLeft);
4. let tr = intersect(node1.topRight, node2.topRight);
5. let bl = intersect(node1.bottomLeft, node2.bottomLeft);
6. let br = intersect(node1.bottomRight, node2.bottomRight);
7. if (tl.isLeaf && tr.isLeaf && bl.isLeaf && br.isLeaf && tl.val == tr.val == bl.val == br.val) return new Node(tl.val, true);
8. return new Node(false, false, tl, tr, bl, br);
}
